17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	import java.time.temporal.ChronoUnit;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Derives an owner's numeric membership level. Starts at 1, adds 1 when an email is
26	 * present, adds 1 when {@code namesakeCount} is 0, and adds 1 when tenure exceeds
27	 * {@value #TENURE_DAYS} days. Level 4 requires that tenure: because a newly created
28	 * owner has zero tenure, a new owner never exceeds level 3.
29	 */
30	public final class MembershipLevel {
31	
32	    /** Highest level this derivation produces. */
33	    private static final int CAP = 4;
34	
35	    /** Tenure, in days, that must be exceeded for the level-4 factor to apply. */
36	    private static final int TENURE_DAYS = 365;
37	
38	    private MembershipLevel() {
39	    }
40	
41	    /**
42	     * @param owner the owner whose level to derive (its {@code email},
43	     *              {@code namesakeCount} and tenure decide the level).
44	     * @return the membership level, from 1 to {@value #CAP}.
45	     */
46	    public static int of(Owner owner) {
47	        int level = 1;
48	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
49	            level++;
50	        }
51	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
52	            level++;
53	        }
54	        if (tenureDays(owner) > TENURE_DAYS) {
55	            level++;
56	        }
57	        return Math.min(level, CAP);
58	    }
59	
60	    /** Days from the owner's {@code registrationDate} to today, or 0 when unknown. */
61	    private static long tenureDays(Owner owner) {
62	        LocalDate registrationDate = owner.getRegistrationDate();
63	        if (registrationDate == null) {
64	            return 0;
65	        }
66	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
67	    }
68	}
